 "content": "from collections import Counter


def _shape_signature(cells):
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    return frozenset((r - r0, c - c0) for r, c in cells)


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row if v != 0)
    frame = counts.most_common(1)[0][0]

    # The framed panels occupy the left side; their right border is a
    # full-height column of the frame color.
    border_cols = [c for c in range(1, w) if all(grid[r][c] == frame for r in range(h))]
    panel_w = min(border_cols) + 1

    separators = [r for r in range(h) if all(grid[r][c] == frame for c in range(panel_w))]
    templates = []
    for top, bottom in zip(separators, separators[1:]):
        cells = [(r - top - 1, c - 1)
                 for r in range(top + 1, bottom)
                 for c in range(1, panel_w - 1)
                 if grid[r][c] != frame]
        if cells:
            templates.append((top, bottom, frozenset(cells), _shape_signature(cells)))

    objects = {}
    for r in range(h):
        for c in range(panel_w, w):
            v = grid[r][c]
            if v != 0 and v != frame:
                objects.setdefault(v, []).append((r, c))
    object_shapes = {v: _shape_signature(cells) for v, cells in objects.items()}

    out = [row[:panel_w] for row in grid]
    unused = set(objects)
    for top, bottom, cells, signature in templates:
        matches = [v for v in sorted(unused) if object_shapes[v] == signature]
        if not matches:
            continue
        color = matches[0]
        unused.remove(color)
        for rr, cc in cells:
            out[top + 1 + rr][1 + cc] = color
    return out
